import { BRANDING, ForgeError, newId } from "@quinlo/shared";
import type { Deployment, Domain, Store } from "./store";

/**
 * Environments + promotion + Caddy configuration.
 *
 * Promotion copies the live staging deployment's file snapshot to
 * production and marks the previous production deployment superseded.
 * There is no partial state: promotion either creates the new production
 * deployment or throws before touching the old one.
 *
 * Caddyfile generation is pure (unit-tested). The generated file relies
 * on Caddy's automatic HTTPS; live SSL/DNS provisioning is outstanding
 * (see VERIFICATION.md).
 */

export async function promoteToProduction(
  store: Store,
  orgId: string,
  appId: string,
): Promise<Deployment> {
  const staging = await store.getDeployment(orgId, appId, "staging");
  if (!staging) {
    throw new ForgeError("bad_request", "Nothing in staging to promote: deploy to staging first", 400);
  }
  const current = await store.getDeployment(orgId, appId, "production");
  const now = new Date().toISOString();
  const next: Deployment = {
    app_id: appId,
    created_at: now,
    environment: "production",
    files: staging.files.map((f) => ({ ...f })),
    id: newId("dep"),
    org_id: orgId,
    promoted_from: staging.id,
    status: "live",
  };
  await store.createDeployment(next);
  if (current) {
    await store.updateDeployment({ ...current, status: "superseded" });
  }
  return next;
}

export async function deploySnapshot(
  store: Store,
  orgId: string,
  appId: string,
  environment: "production" | "staging",
  files: Array<{ content: string; path: string }>,
): Promise<Deployment> {
  const current = await store.getDeployment(orgId, appId, environment);
  const deployment: Deployment = {
    app_id: appId,
    created_at: new Date().toISOString(),
    environment,
    files: files.map((f) => ({ ...f })),
    id: newId("dep"),
    org_id: orgId,
    promoted_from: null,
    status: "live",
  };
  await store.createDeployment(deployment);
  if (current) {
    await store.updateDeployment({ ...current, status: "superseded" });
  }
  return deployment;
}

export interface CaddyUpstreams {
  production: string;
  staging: string;
}

/**
 * Generate a Caddyfile for an app's custom domains. Each domain proxies
 * to the environment upstream; Caddy handles TLS automatically. A domain
 * pointing at the preview path keeps the app's preview route prefix.
 */
export function generateCaddyfile(domains: Domain[], upstreams: CaddyUpstreams): string {
  const lines: string[] = [
    "# Generated by the " + BRANDING.name + " Studio. Do not edit by hand;",
    "# regenerate from the Deploy view after changing domains.",
    "",
    "{",
    "\tadmin off",
    "}",
    "",
  ];
  const sorted = [...domains].sort((a, b) => a.hostname.localeCompare(b.hostname));
  for (const d of sorted) {
    const upstream = d.environment === "production" ? upstreams.production : upstreams.staging;
    lines.push(`${d.hostname} {`);
    lines.push(`\treverse_proxy ${upstream}`);
    lines.push("\theader {");
    lines.push("\t\tX-Content-Type-Options nosniff");
    lines.push("\t\tReferrer-Policy strict-origin-when-cross-origin");
    lines.push("\t}");
    lines.push("}");
    lines.push("");
  }
  if (sorted.length === 0) {
    lines.push("# No custom domains yet. Add one in the Studio Deploy view.");
  }
  return lines.join("\n");
}

export function previewUrl(baseUrl: string, appId: string, environment: "production" | "staging"): string {
  return `${baseUrl.replace(/\/$/, "")}/preview/${appId}/${environment}/`;
}
